html:
{% set company = frappe.get_doc("Company", doc.company) %}
{% set vendor = frappe.get_doc("Supplier", doc.vendor) %}
{% set vendor_address_name = frappe.db.get_value("Dynamic Link", {"link_doctype": "Supplier", "link_name": doc.vendor,
"parenttype": "Address"}, "parent") %}
{% set addr = frappe.get_doc("Address", vendor_address_name) if vendor_address_name else None %}
{% set curr_sym = "Rs." if doc.currency == "INR" else (doc.currency or "") %}

{# ── AUTO-SELECT LETTERHEAD ── #}
{% if doc.letter_head and frappe.db.exists("Letter Head", doc.letter_head) %}
{% set lh_doc = frappe.get_doc("Letter Head", doc.letter_head) %}
{% elif company.default_letter_head and frappe.db.exists("Letter Head", company.default_letter_head) %}
{% set lh_doc = frappe.get_doc("Letter Head", company.default_letter_head) %}
{% else %}
{% set _lh_name = frappe.db.get_value("Letter Head", {"disabled": 0, "is_default": 1}, "name") %}
{% if _lh_name %}
{% set lh_doc = frappe.get_doc("Letter Head", _lh_name) %}
{% else %}
{% set lh_doc = None %}
{% endif %}
{% endif %}
{% set letterhead_img = lh_doc.image if (lh_doc and lh_doc.image) else "" %}

<style>
  @page {
    size: A4 portrait;
    width: 210mm;
    height: 297mm;
    margin-top: 48mm !important;
    margin-bottom: 20mm !important;
    margin-left: 14mm !important;
    margin-right: 14mm !important;
  }

  * {
    box-sizing: border-box;
  }

  /* ── 100% TRANSPARENT - ZERO WHITE BG ANYWHERE ── */
  html,
  body,
  .print-format-gutter,
  .page-break,
  .po-print-wrapper {
    margin: 0 !important;
    padding: 0 !important;
    background: transparent !important;
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
    border-radius: 0 !important;
    font-family: Arial, Helvetica, sans-serif !important;
    font-size: 9.5px !important;
    color: #000 !important;
    line-height: 1.3 !important;
  }

  .print-format {
    background: transparent !important;
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
    border-radius: 0 !important;
    padding: 0 !important;
    margin-top: 48mm !important;
    margin-bottom: 20mm !important;
    margin-left: 14mm !important;
    margin-right: 14mm !important;
    font-family: Arial, Helvetica, sans-serif !important;
    font-size: 9.5px !important;
    color: #000 !important;
    line-height: 1.3 !important;
  }

  @media screen {
    .print-format-gutter {
      background-color: transparent !important;
      padding: 0 !important;
    }
    .print-format {
      background-color: transparent !important;
      background: transparent !important;
      box-shadow: none !important;
      border-radius: 0 !important;
      padding: 0 !important;
      margin-top: 48mm !important;
      margin-bottom: 20mm !important;
      margin-left: 14mm !important;
      margin-right: 14mm !important;
      max-width: 100% !important;
      min-height: auto !important;
    }
  }

  p {
    margin: 3px 0;
  }

  /* Hide default Frappe headers to avoid duplicate rendering */
  .letter-head,
  .print-heading,
  .letter-head-footer {
    display: none !important;
  }

  .po-print-wrapper {
    width: 100% !important;
    margin: 0 !important;
    padding: 0 !important;
    background: transparent !important;
    background-color: transparent !important;
  }

  /* Fixed-layout formal tables matching exact original specification */
  table.fixed {
    width: 100%;
    table-layout: fixed;
    border-collapse: collapse;
    margin-bottom: 6px;
    word-wrap: break-word;
    background: transparent !important;
    background-color: transparent !important;
  }

  table.fixed th,
  table.fixed td {
    border: 1px solid #000 !important;
    padding: 3px 5px !important;
    vertical-align: top !important;
    font-family: Arial, Helvetica, sans-serif !important;
    font-size: 9px !important;
    color: #000 !important;
    background: transparent !important;
    background-color: transparent !important;
  }

  table.fixed thead th {
    background: transparent !important;
    background-color: transparent !important;
    font-weight: bold !important;
    text-align: left;
  }

  table.fixed .right {
    text-align: right;
  }

  table.fixed .center {
    text-align: center;
  }

  .lbl {
    font-weight: bold !important;
  }

  .section-head {
    background: transparent !important;
    background-color: transparent !important;
    font-weight: bold !important;
    padding: 3px 6px !important;
    border: 1px solid #000 !important;
    border-bottom: none !important;
    font-size: 9px !important;
    text-transform: uppercase !important;
    letter-spacing: 0.5px !important;
  }

  tr {
    page-break-inside: avoid !important;
  }

  .standard-terms-print ol,
  .standard-terms-print ul {
    margin-top: 2px !important;
    margin-bottom: 4px !important;
    padding-left: 18px !important;
  }

  .standard-terms-print li {
    margin-bottom: 2px !important;
  }

  @media screen {
    .po-screen-watermark {
      display: block;
      position: fixed;
      top: 42%;
      left: 50%;
      transform: translate(-50%, -50%) rotate(-35deg);
      -webkit-transform: translate(-50%, -50%) rotate(-35deg);
      font-size: 68px;
      font-weight: 900;
      color: rgba(220, 38, 38, 0.50);
      border: 6px dashed rgba(220, 38, 38, 0.50);
      border-radius: 16px;
      padding: 16px 40px;
      letter-spacing: 8px;
      text-transform: uppercase;
      pointer-events: none;
      z-index: 9999;
      white-space: nowrap;
    }
  }
  @media print {
    .po-screen-watermark {
      display: none !important;
    }
  }
</style>

<div class="po-print-wrapper">
  {% set po_state = (doc.workflow_state or "Draft") | trim %}
  {% if po_state != "Approved" %}
    {% if po_state == "Draft" %}
      {% set watermark_text = "DRAFT" %}
    {% elif po_state == "Generated (Yet to be Verified)" %}
      {% set watermark_text = "NOT COMPLETED" %}
    {% elif po_state == "Verified (Yet to be approved)" %}
      {% set watermark_text = "NOT APPROVED" %}
    {% elif po_state == "Cancelled" %}
      {% set watermark_text = "CANCELLED" %}
    {% else %}
      {% set watermark_text = "NOT APPROVED" %}
    {% endif %}
    <div class="po-screen-watermark">{{ watermark_text }}</div>
  {% endif %}

  <!-- ── PO TITLE ── -->
  <p
    style="text-align:center; font-size:13px; font-weight:bold; text-decoration:underline; margin:0 0 6px 0; letter-spacing:1px;">
    PURCHASE ORDER</p>

  <!-- ── VENDOR (LEFT) + PO META (RIGHT) ── -->
  <table class="fixed" style="margin-bottom:6px;">
    <colgroup>
      <col style="width:58%">
      <col style="width:22%">
      <col style="width:20%">
    </colgroup>
    <tbody>
      <tr>
        <td rowspan="6" style="vertical-align:top; border-right:2px solid #000 !important;">
          <span class="lbl">{{ vendor.supplier_name }}</span><br>
          {% if addr %}
          {% if addr.address_line1 %}{{ addr.address_line1 }},<br>{% endif %}
          {% if addr.address_line2 %}{{ addr.address_line2 }},<br>{% endif %}
          {% if addr.city %}{{ addr.city }}{% if addr.pincode %} – {{ addr.pincode }}{% endif %}.<br>{% endif %}
          {% if addr.state %}{{ addr.state }},<br>{% endif %}
          {% if addr.country %}{{ addr.country }}.<br>{% endif %}
          {% else %}
          (No address on file)<br>
          {% endif %}
          {% if doc.vendor_gstin %}<br><span class="lbl">GSTIN:</span> {{ doc.vendor_gstin }}{% endif %}
          {% if doc.vendor_pan %}<br><span class="lbl">PAN:</span> {{ doc.vendor_pan }}{% endif %}
        </td>
        <td class="lbl" style="border-bottom:none !important;">Ref No. :-</td>
        <td style="border-bottom:none !important; border-left:1px solid #000 !important;">{{ doc.name }}</td>
      </tr>
      <tr>
        <td class="lbl" style="border-top:1px solid #000 !important; border-bottom:none !important;">Date :-</td>
        <td
          style="border-top:1px solid #000 !important; border-bottom:none !important; border-left:1px solid #000 !important;">
          {{ frappe.utils.formatdate(doc.po_date, "dd-mm-yyyy") }}</td>
      </tr>
      <tr>
        <td class="lbl" style="border-top:1px solid #000 !important; border-bottom:none !important;">Quotation No. :-
        </td>
        <td
          style="border-top:1px solid #000 !important; border-bottom:none !important; border-left:1px solid #000 !important;">
          {{ doc.quotation_ref or "—" }}</td>
      </tr>
      <tr>
        <td class="lbl" style="border-top:1px solid #000 !important; border-bottom:none !important;">Quotation Date :-
        </td>
        <td
          style="border-top:1px solid #000 !important; border-bottom:none !important; border-left:1px solid #000 !important;">
          {{ doc.get_formatted("quotation_date") or "—" }}</td>
      </tr>
      <tr>
        <td class="lbl" style="border-top:1px solid #000 !important; border-bottom:none !important;">PI No. :-</td>
        <td
          style="border-top:1px solid #000 !important; border-bottom:none !important; border-left:1px solid #000 !important;">
          {{ doc.pi_number or "—" }}</td>
      </tr>
      <tr>
        <td class="lbl" style="border-top:1px solid #000 !important;">Currency :-</td>
        <td style="border-top:1px solid #000 !important; border-left:1px solid #000 !important;">{{ doc.currency or "INR" }}</td>
      </tr>
    </tbody>
  </table>

  <!-- ── SALUTATION ── -->
  <p>Dear Sir/Ma'am,</p>
  <p>We are pleased to release this Purchase Order for the supply of following items. Details and specifications
    are as per below. Please send your acceptance confirmation via return email for further processing.</p>

  <!-- ── PRE-CONDITIONS ── -->
  <table class="fixed" style="margin-bottom:6px;">
    <tbody>
      <tr>
        <td>
          The bill should be raised in the name of <strong>{{ company.company_name }}</strong>.
          {% set comp_desc = company.registration_details or company.company_description or "" %}
          {% set raw_address = doc.company_address or comp_desc or "" %}
          {% set addr_lines = raw_address.split("\n") %}
          {% set clean_lines = [] %}
          {% for line in addr_lines %}
            {% set stripped = line.strip() %}
            {% if stripped and not stripped.startswith("Tax ID") and not stripped.startswith("GSTIN") and not stripped.startswith("PAN:") and not stripped.startswith("PAN :") %}
              {% set _ = clean_lines.append(stripped) %}
            {% endif %}
          {% endfor %}
          {% if clean_lines %}
          <br><span style="color:#333; font-size:8.5px;">{{ clean_lines | join("<br>") }}</span>
          {% endif %}
          {% set tax_val = doc.company_gstin or company.tax_id %}
          {% set pan_val = doc.company_pan or company.get("custom_pan") or company.get("pan") %}
          {% if not pan_val and tax_val and tax_val|length == 15 %}
            {% set pan_val = tax_val[2:12] %}
          {% endif %}
          <br><span style="color:#333; font-size:8.5px;">Tax ID / GSTIN: {{ tax_val or "—" }}</span>
          <br><span style="color:#333; font-size:8.5px;">PAN: {{ pan_val or "—" }}</span>
        </td>
      </tr>
      <tr>
        <td style="border-top:none !important;">The bill and delivery challan must clearly mention the Purchase Order
          number.</td>
      </tr>
      <tr>
        <td style="border-top:none !important;">The bill must clearly mention the applicable HSN/SAC codes as required
          under GST law.</td>
      </tr>
      <tr>
        <td style="border-top:none !important;">Original signed invoice and relevant documents must be provided at the
          time of material delivery.</td>
      </tr>
      <tr>
        <td style="border-top:none !important;">If nothing contrary is heard within 24 hours from receipt of this PO, it
          will be understood that the Purchase Order is accepted by you.</td>
      </tr>
      <tr>
        <td style="border-top:none !important;">This Purchase Order shall be subject to the jurisdiction of the
          Company's registered office.</td>
      </tr>
    </tbody>
  </table>

  <!-- ── ITEM TABLE ── -->
  <table class="fixed" style="margin-bottom:6px;">
    <colgroup>
      <col style="width:5%">
      <col style="width:30%">
      <col style="width:9%">
      <col style="width:9%">
      <col style="width:6%">
      <col style="width:6%">
      <col style="width:17%">
      <col style="width:18%">
    </colgroup>
    <thead>
      <tr>
        <th class="center">S.No</th>
        <th>Particulars / Item Description</th>
        <th class="center">HSN Code</th>
        <th class="center">Brand / Make</th>
        <th class="center">UOM</th>
        <th class="center">Qty</th>
        <th class="right">Rate ({{ curr_sym }})</th>
        <th class="right">Amount ({{ curr_sym }})</th>
      </tr>
    </thead>
    <tbody>
      {% if doc.items and doc.items|length > 0 %}
      {% for item in doc.items %}
      <tr>
        <td class="center" style="border-top:none !important;">{{ loop.index }}</td>
        <td style="border-top:none !important;">
          <strong>{{ item.equipment_name or item.equipment or "—" }}</strong><br>
          {% if item.brand %}Brand: {{ item.brand }} | {% endif %}
          {% if item.manufacturer %}Mfr: {{ item.manufacturer }}<br>{% endif %}
          {% if item.specification %}<span style="font-size:8.5px;">{{ item.specification }}</span>{% endif %}
        </td>
        <td class="center" style="border-top:none !important;">{{ item.hsn_code or "—" }}</td>
        <td class="center" style="border-top:none !important;">{{ item.brand or "—" }}</td>
        <td class="center" style="border-top:none !important;">{{ item.unit or "Nos" }}</td>
        <td class="center" style="border-top:none !important;">{{ item.quantity }}</td>
        <td class="right" style="border-top:none !important;">{{ curr_sym }} {{ frappe.utils.fmt_money(item.rate, currency=None) }}</td>
        <td class="right" style="border-top:none !important;">{{ curr_sym }} {{ frappe.utils.fmt_money(item.taxable_amount, currency=None) }}</td>
      </tr>
      {% endfor %}
      {% else %}
      <tr>
        <td class="center" style="border-top:none !important;">1</td>
        <td style="border-top:none !important;">
          <strong>{{ doc.equipment_name or doc.equipment or "—" }}</strong><br>
          {% if doc.manufacturer %}Mfr: {{ doc.manufacturer }}<br>{% endif %}
          {% if doc.country_of_origin %}Origin: {{ doc.country_of_origin }}<br>{% endif %}
          {% if doc.specification %}<span style="font-size:8.5px;">{{ doc.specification }}</span>{% endif %}
        </td>
        <td class="center" style="border-top:none !important;">{{ doc.hsn_code or "—" }}</td>
        <td class="center" style="border-top:none !important;">{{ doc.brand or "—" }}</td>
        <td class="center" style="border-top:none !important;">{{ doc.unit or "Nos" }}</td>
        <td class="center" style="border-top:none !important;">{{ doc.quantity }}</td>
        <td class="right" style="border-top:none !important;">{{ curr_sym }} {{ frappe.utils.fmt_money(doc.rate, currency=None) }}</td>
        <td class="right" style="border-top:none !important;">{{ curr_sym }} {{ frappe.utils.fmt_money(doc.taxable_value, currency=None) }}</td>
      </tr>
      {% endif %}

      <!-- Taxable Amount Row (Reflecting before GST) -->
      <tr>
        <td colspan="7" class="right lbl" style="border-top:none !important;">Taxable Amount</td>
        <td class="right lbl" style="border-top:none !important;">{{ curr_sym }} {{ frappe.utils.fmt_money(doc.taxable_value or doc.cumulative_items_total or 0, currency=None) }}</td>
      </tr>

      <!-- Tax rows: GST Amount -->
      {% if doc.tax_amount and doc.tax_amount > 0 %}
      <tr>
        <td colspan="7" class="right lbl" style="border-top:none !important;">GST Amount{% if doc.gst_percentage %} @ {{ doc.gst_percentage }}%{% endif %}</td>
        <td class="right" style="border-top:none !important;">{{ curr_sym }} {{ frappe.utils.fmt_money(doc.tax_amount, currency=None) }}</td>
      </tr>
      {% elif doc.igst_amount and doc.igst_amount > 0 %}
      <tr>
        <td colspan="7" class="right lbl" style="border-top:none !important;">GST Amount{% if doc.gst_percentage %} @ {{ doc.gst_percentage }}%{% endif %}</td>
        <td class="right" style="border-top:none !important;">{{ curr_sym }} {{ frappe.utils.fmt_money(doc.igst_amount, currency=None) }}</td>
      </tr>
      {% endif %}

      {% if doc.freight and doc.freight > 0 %}
      <tr>
        <td colspan="7" class="right" style="border-top:none !important;">Freight Charges</td>
        <td class="right" style="border-top:none !important;">{{ curr_sym }} {{ frappe.utils.fmt_money(doc.freight, currency=None) }}</td>
      </tr>
      {% endif %}
      {% if doc.insurance and doc.insurance > 0 %}
      <tr>
        <td colspan="7" class="right" style="border-top:none !important;">Insurance Charges</td>
        <td class="right" style="border-top:none !important;">{{ curr_sym }} {{ frappe.utils.fmt_money(doc.insurance, currency=None) }}</td>
      </tr>
      {% endif %}
      {% if doc.custom_charges and doc.custom_charges > 0 %}
      <tr>
        <td colspan="7" class="right" style="border-top:none !important;">Custom Clearance Charges</td>
        <td class="right" style="border-top:none !important;">{{ curr_sym }} {{ frappe.utils.fmt_money(doc.custom_charges, currency=None) }}</td>
      </tr>
      {% endif %}
      {% if doc.other_charges and doc.other_charges > 0 %}
      <tr>
        <td colspan="7" class="right" style="border-top:none !important;">Other Charges</td>
        <td class="right" style="border-top:none !important;">{{ curr_sym }} {{ frappe.utils.fmt_money(doc.other_charges, currency=None) }}</td>
      </tr>
      {% endif %}

      <tr>
        <td colspan="7" class="right lbl" style="border-top:none !important;">TOTAL</td>
        <td class="right lbl" style="border-top:none !important;">{{ curr_sym }} {{
          frappe.utils.fmt_money(doc.grand_total, currency=None) }}</td>
      </tr>
      <tr>
        <td colspan="7" class="right lbl" style="border-top:none !important; font-size:10px;">Total Payable Amount</td>
        <td class="right lbl" style="border-top:none !important; font-size:10px;">{{ curr_sym }} {{
          frappe.utils.fmt_money(doc.grand_total, currency=None) }}</td>
      </tr>
    </tbody>
  </table>

  <!-- ── PAYMENT + LOGISTICS (SIDE BY SIDE) ── -->
  <table width="100%" cellspacing="0" cellpadding="0"
    style="border-collapse:collapse; margin-bottom:6px; table-layout:fixed; background:transparent !important;">
    <colgroup>
      <col style="width:50%">
      <col style="width:4px">
      <col style="width:50%">
    </colgroup>
    <tr>
      <!-- Payment -->
      <td style="vertical-align:top; padding-right:4px; border:none !important; background:transparent !important;">
        <div class="section-head">PAYMENT DETAILS</div>
        <table class="fixed" style="margin-bottom:0;">
          <colgroup>
            <col style="width:45%">
            <col style="width:55%">
          </colgroup>
          <tbody>
            <tr>
              <td class="lbl">Payment Terms</td>
              <td>{{ doc.payment_terms or "—" }}</td>
            </tr>
            <tr>
              <td class="lbl" style="border-top:none !important;">Advance %</td>
              <td style="border-top:none !important;">{{ doc.advance_percentage or 0 }}%</td>
            </tr>
            <tr>
              <td class="lbl" style="border-top:none !important;">Advance Amount</td>
              <td style="border-top:none !important;">{{ curr_sym }} {{ frappe.utils.fmt_money(doc.advance_amount or 0, currency=None) }}</td>
            </tr>
            <tr>
              <td class="lbl" style="border-top:none !important;">Balance Due</td>
              <td class="lbl" style="border-top:none !important;">{{ curr_sym }} {{ frappe.utils.fmt_money(doc.balance_due or doc.grand_total or 0, currency=None) }}</td>
            </tr>
            <tr>
              <td class="lbl" style="border-top:none !important;">Vendor Bank</td>
              <td style="border-top:none !important;">{{ doc.vendor_bank_name or "—" }}</td>
            </tr>
            <tr>
              <td class="lbl" style="border-top:none !important;">A/C No.</td>
              <td style="border-top:none !important;">{{ doc.vendor_account_number or "—" }}</td>
            </tr>
            <tr>
              <td class="lbl" style="border-top:none !important;">IFSC Code</td>
              <td style="border-top:none !important;">{{ doc.vendor_ifsc or "—" }}</td>
            </tr>
          </tbody>
        </table>
      </td>
      <td style="border:none !important; background:transparent !important;"></td>
      <!-- Logistics -->
      <td style="vertical-align:top; padding-left:4px; border:none !important; background:transparent !important;">
        <div class="section-head">LOGISTICS &amp; SHIPPING</div>
        {% set dest_check = ((doc.warehouse or "") + " " + (doc.delivery_location or "")) | lower %}
        {% set is_dest_india = "india" in dest_check or "maharashtra" in dest_check or "gujarat" in dest_check or "karnataka" in dest_check or "tamil nadu" in dest_check or "telangana" in dest_check or "andhra" in dest_check or "delhi" in dest_check or "rajasthan" in dest_check or "haryana" in dest_check or "uttar pradesh" in dest_check or "madhya pradesh" in dest_check or "kerala" in dest_check or "punjab" in dest_check or "west bengal" in dest_check or "nashik" in dest_check or "mumbai" in dest_check or "pune" in dest_check or "ahmedabad" in dest_check or "bangalore" in dest_check or "chennai" in dest_check or "hyderabad" in dest_check or "kolkata" in dest_check or (not doc.warehouse and not doc.delivery_location) or (doc.currency == "INR" and not ("uae" in dest_check or "dubai" in dest_check or "usa" in dest_check or "uk" in dest_check or "china" in dest_check or "africa" in dest_check or "singapore" in dest_check)) %}
        <table class="fixed" style="margin-bottom:0;">
          <colgroup>
            <col style="width:45%">
            <col style="width:55%">
          </colgroup>
          <tbody>
            {% if not is_dest_india %}
            <tr>
              <td class="lbl">Port of Shipment</td>
              <td>{{ doc.port or company.custom_default_port or "—" }}</td>
            </tr>
            <tr>
              <td class="lbl" style="border-top:none !important;">Shipment Type</td>
              <td style="border-top:none !important;">{{ doc.shipment_type or "—" }}</td>
            </tr>
            {% endif %}
            <tr>
              <td class="lbl"{% if not is_dest_india %} style="border-top:none !important;"{% endif %}>Expected Delivery</td>
              <td{% if not is_dest_india %} style="border-top:none !important;"{% endif %}>{{ doc.get_formatted("expected_delivery") or "—" }}</td>
            </tr>
            {% if doc.delivery_location %}
            <tr>
              <td class="lbl" style="border-top:none !important;">Delivery Location</td>
              <td style="border-top:none !important;">{{ doc.delivery_location }}</td>
            </tr>
            {% else %}
            <tr>
              <td class="lbl" style="border-top:none !important;">Mode of Transport</td>
              <td style="border-top:none !important;">{{ doc.transport_mode or "Road" }}</td>
            </tr>
            {% set mode = (doc.transport_mode or "Road")|lower %}
            {% if "road" in mode or (not doc.transport_mode and (doc.transporter_name or doc.vehicle_number or doc.lr_number or doc.eway_bill_number)) %}
              {% if doc.transporter_name %}
              <tr>
                <td class="lbl" style="border-top:none !important;">Transporter</td>
                <td style="border-top:none !important;">{{ doc.transporter_name }}</td>
              </tr>
              {% endif %}
              {% if doc.vehicle_number %}
              <tr>
                <td class="lbl" style="border-top:none !important;">Vehicle Number</td>
                <td style="border-top:none !important;">{{ doc.vehicle_number }}</td>
              </tr>
              {% endif %}
              {% if doc.lr_number %}
              <tr>
                <td class="lbl" style="border-top:none !important;">LR / Consignment No.</td>
                <td style="border-top:none !important;">{{ doc.lr_number }}</td>
              </tr>
              {% endif %}
              {% if doc.eway_bill_number %}
              <tr>
                <td class="lbl" style="border-top:none !important;">E-Way Bill No.</td>
                <td style="border-top:none !important;">{{ doc.eway_bill_number }}</td>
              </tr>
              {% endif %}
            {% elif "air" in mode %}
              {% if doc.airport %}
              <tr>
                <td class="lbl" style="border-top:none !important;">Airport</td>
                <td style="border-top:none !important;">{{ doc.airport }}</td>
              </tr>
              {% endif %}
              {% if doc.air_carrier %}
              <tr>
                <td class="lbl" style="border-top:none !important;">Air Carrier</td>
                <td style="border-top:none !important;">{{ doc.air_carrier }}</td>
              </tr>
              {% endif %}
              {% if doc.flight_number %}
              <tr>
                <td class="lbl" style="border-top:none !important;">Flight Number</td>
                <td style="border-top:none !important;">{{ doc.flight_number }}</td>
              </tr>
              {% endif %}
              {% if doc.awb_number %}
              <tr>
                <td class="lbl" style="border-top:none !important;">AWB Number</td>
                <td style="border-top:none !important;">{{ doc.awb_number }}</td>
              </tr>
              {% endif %}
            {% elif "sea" in mode %}
              {% if doc.port %}
              <tr>
                <td class="lbl" style="border-top:none !important;">Port of Shipment</td>
                <td style="border-top:none !important;">{{ doc.port }}</td>
              </tr>
              {% endif %}
              {% if doc.shipment_type %}
              <tr>
                <td class="lbl" style="border-top:none !important;">Shipment Type</td>
                <td style="border-top:none !important;">{{ doc.shipment_type }}{% if doc.shipment_subtype %} ({{ doc.shipment_subtype }}){% endif %}</td>
              </tr>
              {% endif %}
              {% if doc.cha %}
              <tr>
                <td class="lbl" style="border-top:none !important;">CHA Agent</td>
                <td style="border-top:none !important;">{{ doc.cha }}</td>
              </tr>
              {% endif %}
            {% elif "courier" in mode %}
              {% if doc.courier_service %}
              <tr>
                <td class="lbl" style="border-top:none !important;">Courier Service</td>
                <td style="border-top:none !important;">{{ doc.courier_service }}</td>
              </tr>
              {% endif %}
              {% if doc.tracking_number %}
              <tr>
                <td class="lbl" style="border-top:none !important;">Tracking / Docket No.</td>
                <td style="border-top:none !important;">{{ doc.tracking_number }}</td>
              </tr>
              {% endif %}
            {% endif %}
            {% endif %}
            {% if doc.warehouse %}
            <tr>
              <td class="lbl" style="border-top:none !important;">Destination Warehouse</td>
              <td style="border-top:none !important;">{{ doc.warehouse|replace('\n', '<br>') }}</td>
            </tr>
            {% endif %}
            {% if doc.container_number %}
            <tr>
              <td class="lbl" style="border-top:none !important;">Container No.</td>
              <td style="border-top:none !important;">{{ doc.container_number }}</td>
            </tr>
            {% endif %}
            <tr>
              <td class="lbl" style="border-top:none !important;">SRI GSTIN</td>
              <td style="border-top:none !important;">{{ company.tax_id or "—" }}</td>
            </tr>
            <tr>
              <td class="lbl" style="border-top:none !important;">IEC Code</td>
              <td style="border-top:none !important;">{{ company.custom_import_export_code or "AFTFS2557J" }}</td>
            </tr>
          </tbody>
        </table>
      </td>
    </tr>
  </table>

  <!-- ── TERMS & CONDITIONS ── -->
  <div style="margin-top: 6px;"></div>
  {% set rendered_custom_terms = doc.custom_terms or frappe.db.get_value("Vendor Purchase Order", doc.name, "custom_terms") %}
  {% set st_terms_list = [] %}
  {% if doc.standard_terms %}
    {% for row in doc.standard_terms|sort(attribute="idx") %}
      {% if row.standard_term and frappe.db.exists("Terms and Conditions", row.standard_term) %}
        {% set st_doc = frappe.get_doc("Terms and Conditions", row.standard_term) %}
        {% set _ = st_terms_list.append({"title": row.standard_term, "terms": st_doc.terms}) %}
      {% endif %}
    {% endfor %}
  {% endif %}

  {# Fetch default Terms and Conditions from the database if neither custom nor standard terms are explicitly set on doc #}
  {% if not rendered_custom_terms and not st_terms_list %}
    {% set default_term_name = "Standard Domestic PO Terms" if is_dest_india else "Standard Export PO Terms" %}
    {% if not frappe.db.exists("Terms and Conditions", default_term_name) %}
      {% set default_term_name = "Standard Export PO Terms" if frappe.db.exists("Terms and Conditions", "Standard Export PO Terms") else None %}
    {% endif %}
    {% if not default_term_name %}
      {% set any_term = frappe.db.get_value("Terms and Conditions", {}, "name") %}
      {% if any_term %}{% set default_term_name = any_term %}{% endif %}
    {% endif %}
    {% if default_term_name and frappe.db.exists("Terms and Conditions", default_term_name) %}
      {% set st_doc = frappe.get_doc("Terms and Conditions", default_term_name) %}
      {% set _ = st_terms_list.append({"title": default_term_name, "terms": st_doc.terms}) %}
    {% endif %}
  {% endif %}

  <p style="margin:0 0 4px 0;"><strong><u>Terms &amp; Conditions :-</u></strong></p>
  <table class="fixed" style="margin-bottom:8px;">
    <tbody>
      <tr>
        <td style="line-height:1.4;">
          {% if st_terms_list %}
            {% for item in st_terms_list %}
              <div class="standard-terms-print" style="margin-bottom: 6px;">
                {% if st_terms_list|length > 1 %}<strong>{{ item.title }}</strong>{% endif %}
                <div>{{ item.terms|safe }}</div>
              </div>
            {% endfor %}
          {% endif %}
          {% if rendered_custom_terms %}
            <div class="custom-terms-print" style="{% if st_terms_list %}margin-top: 6px;{% endif %}">
              {{ rendered_custom_terms|safe }}
            </div>
          {% endif %}
          {% if doc.custom_terms %}
          <div class="custom-terms-print" style="margin-top: 6px;">
            {{ doc.custom_terms }}
          </div>
          {% endif %}
        </td>
      </tr>
    </tbody>
  </table>

  <!-- ── ATTACHED DOCUMENTS INDEX (IF ANY) ── -->
  {% set attached_docs = [] %}
  {% if doc.quotation_pdf %}
  {% set _ = attached_docs.append({"category": "Vendor Quotation", "filename": doc.quotation_pdf.split('/')[-1]}) %}
  {% endif %}
  {% if doc.supplier_quotation_attachment %}
  {% set _ = attached_docs.append({"category": "Supplier Quotation Document", "filename":
  doc.supplier_quotation_attachment.split('/')[-1]}) %}
  {% endif %}
  {% if doc.quotation_comparision %}
  {% set _ = attached_docs.append({"category": "Quotation Comparison Sheet", "filename":
  doc.quotation_comparision.split('/')[-1]}) %}
  {% endif %}
  {% if doc.inspection_report %}
  {% set _ = attached_docs.append({"category": "Pre-dispatch Inspection Report", "filename":
  doc.inspection_report.split('/')[-1]}) %}
  {% endif %}

  {% if attached_docs | length > 0 %}
  <div class="section-head">ATTACHED DOCUMENTS SUMMARY</div>
  <table class="fixed" style="margin-bottom:8px;">
    <colgroup>
      <col style="width:8%">
      <col style="width:42%">
      <col style="width:50%">
    </colgroup>
    <thead>
      <tr>
        <th class="center">S.No</th>
        <th>Document Category / Label</th>
        <th>File Name / Reference</th>
      </tr>
    </thead>
    <tbody>
      {% for item in attached_docs %}
      <tr>
        <td class="center" style="border-top:none !important;">{{ loop.index }}</td>
        <td style="border-top:none !important;"><strong>{{ item.category }}</strong></td>
        <td style="border-top:none !important;">{{ item.filename }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>
  {% endif %}

  {% if doc.remarks %}
  <div class="section-head">NOTE</div>
  <table class="fixed" style="margin-bottom:8px;">
    <tbody>
      <tr>
        <td>{{ doc.remarks }}</td>
      </tr>
    </tbody>
  </table>
  {% endif %}

  <!-- ── SIGNATURES ── -->
  <table width="100%" cellspacing="0" cellpadding="0"
    style="border-collapse:collapse; margin-top:18px; margin-bottom:8px; table-layout:fixed; background:transparent !important;">
    <colgroup>
      <col style="width:33%">
      <col style="width:34%">
      <col style="width:33%">
    </colgroup>
    <tr style="background:transparent !important;">
      <td
        style="text-align:center; border-top:1px solid #000 !important; padding-top:4px; border-left:none !important; border-right:none !important; border-bottom:none !important; background:transparent !important;">
        <strong>Prepared By</strong><br>
        <span style="font-size:9px; color:#333;">{{ doc.prepared_by or "Administrator" }}</span>
      </td>
      <td
        style="text-align:center; border-top:1px solid #000 !important; padding-top:4px; border-left:none !important; border-right:none !important; border-bottom:none !important; background:transparent !important;">
        <strong>Verified By</strong><br>
        <span style="font-size:9px; color:#333;">{{ doc.verified_by or "Administrator" }}</span>
      </td>
      <td
        style="text-align:center; border-top:1px solid #000 !important; padding-top:4px; border-left:none !important; border-right:none !important; border-bottom:none !important; background:transparent !important;">
        <strong>Authorized Signatory</strong><br>
        <span style="font-size:9px; color:#333;">For {{ company.company_name }}</span>
      </td>
    </tr>
  </table>

</div>
